  "id": "spheniscus-demersus",
  "name": "Zwartvoetpinguïn",
  "sci": "Spheniscus demersus",
  "cat": "Zeevogels",
  "intro": "De zwartvoetpinguïn of brilpinguïn is een vogel uit de familie van de pinguïns.",
